html:
{%- set d = get_cb_print_data(doc.name) -%}
{%- set f = d.form -%}
{%- set s = d.sheet -%}

{%- macro fmt(v) -%}{{ '{:,.2f}'.format((v or 0)|float) }}{%- endmacro -%}
{%- macro fmtq(v) -%}
  {%- set n = (v or 0)|float -%}
  {%- if n == n|int -%}{{ n|int }}{%- else -%}{{ '{:g}'.format(n) }}{%- endif -%}
{%- endmacro -%}

<style>
  .pcs { font-family: Arial, Helvetica, sans-serif; font-size: 11.5px; color: #222; }
  .pcs-meta { text-align:right; font-size:9px; color:#666; margin-bottom:4px; line-height:1.5; }
  .pcs-hdr  { margin-bottom:6px; }
  .pcs-hdr img { height:55px; display:block; margin-bottom:2px; }
  .pcs-co   { font-size:12px; font-weight:bold; }
  .pcs-title{ text-align:center; font-size:14px; font-weight:bold; margin:8px 0 14px; }
  .info-tbl { width:auto; margin-bottom:14px; border-collapse:collapse; }
  .info-tbl td { padding:2px 4px; vertical-align:top; font-size:11.5px; }
  .info-tbl td:first-child { font-weight:bold; white-space:nowrap; padding-right:10px; }
  .cost-tbl { width:100%; border-collapse:collapse; margin-bottom:14px; font-size:11.5px; }
  .cost-tbl th { background:#2b2b2b; color:#fff; padding:6px 8px; text-align:center; font-size:11px; border:1px solid #555; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .cost-tbl th:first-child { text-align:left; }
  .cost-tbl td { padding:4px 8px; border-bottom:1px solid #eee; }
  .cost-tbl td.r { text-align:right; }
  .cost-tbl td.c { text-align:center; }
  .cost-tbl tr:nth-child(even) td { background:#fafafa; }
  .grp-row td { background:#37475a !important; color:#fff; font-weight:bold; padding:5px 8px; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .sum-tbl-outer { width:100%; border-collapse:collapse; margin-bottom:14px; }
  .sum-tbl-outer > tbody > tr > td { vertical-align:top; }
  .sum-left { font-size:11.5px; line-height:1.8; padding-right:20px; }
  .sum-right-tbl { width:100%; border-collapse:collapse; }
  .sum-right-tbl td { padding:3px 6px; font-size:11.5px; }
  .sum-right-tbl td:last-child { text-align:right; font-weight:600; white-space:nowrap; }
  .sum-right-tbl .sep td { border-top:1px solid #ccc; padding-top:5px; }
  .lbl { font-weight:bold; margin-top:10px; margin-bottom:3px; font-size:11.5px; }
  .mat-tbl { width:100%; border-collapse:collapse; font-size:11px; }
  .mat-tbl th { background:#444; color:#fff; padding:5px 8px; text-align:left; border:1px solid #666; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  .mat-tbl td { padding:4px 8px; border:1px solid #ddd; }
</style>

<div class="pcs">

  <div class="pcs-meta">
    Created at {{ d.created_date }} by {{ d.created_by }}<br>
    Updated at {{ d.updated_date }} by {{ d.updated_by }}
  </div>

  <div class="pcs-hdr">
    {% set logo = frappe.db.get_single_value('Website Settings','banner_image') or '' %}
    {% if logo %}<img src="{{ logo }}">{% endif %}
    <div class="pcs-co">Savinda Graphic Systems (Pvt) Ltd.</div>
  </div>

  <div class="pcs-title">Product Costing Summary</div>

  <table class="info-tbl">
    <tr><td>Sales Inquiry</td>       <td>: {{ d.doc.ref or '' }}</td></tr>
    <tr><td>Customer</td>            <td>: {{ d.doc.customer_name or '' }}</td></tr>
    <tr><td>Inquiry Breakdown</td>   <td>: {{ d.breakdown_name }}</td></tr>
    <tr><td>Breakdown Quantity</td>  <td>: {{ d.item_qty | int }}</td></tr>
  </table>

  <table class="cost-tbl">
    <thead>
      <tr>
        <th style="width:44%">DESCRIPTION</th>
        <th style="width:14%">ESTIMATED QTY.</th>
        <th style="width:21%">UNIT PRICE(LKR)</th>
        <th style="width:21%">AMOUNT(LKR)</th>
      </tr>
    </thead>
    <tbody>

      {%- if d.prep_rows %}
      <tr class="grp-row">
        <td>Preparation Costs</td><td></td><td></td>
        <td class="r">{{ fmt(d.group_totals.get('preparation',0)) }}</td>
      </tr>
      {%- for row in d.prep_rows %}
      <tr>
        <td>{{ row._desc }}</td>
        <td class="c">{{ fmtq(row.req_qty) }}</td>
        <td class="r">{{ fmt(row.rate) if row.rate else '' }}</td>
        <td class="r">{{ fmt(row.amount) }}</td>
      </tr>
      {%- endfor %}
      {%- endif %}

      {%- if d.mat_rows %}
      <tr class="grp-row">
        <td>Material Costs</td><td></td><td></td>
        <td class="r">{{ fmt(d.group_totals.get('material',0)) }}</td>
      </tr>
      {%- for row in d.mat_rows %}
      <tr>
        <td>{{ row._desc }}</td>
        <td class="c">{{ fmtq(row.req_qty) }}</td>
        <td class="r">{{ fmt(row.rate) if row.rate else '' }}</td>
        <td class="r">{{ fmt(row.amount) }}</td>
      </tr>
      {%- endfor %}
      {%- endif %}

      {%- if d.prod_rows %}
      <tr class="grp-row">
        <td>{{ 'Over Head Costs' if d.is_flexo else 'Production Costs' }}</td><td></td><td></td>
        <td class="r">{{ fmt(d.group_totals.get('production',0)) }}</td>
      </tr>
      {%- for row in d.prod_rows %}
      <tr>
        <td>{{ row._desc }}</td>
        <td class="c">{{ fmtq(row.req_qty) }}</td>
        <td class="r">{{ fmt(row.rate) if row.rate else '' }}</td>
        <td class="r">{{ fmt(row.amount) }}</td>
      </tr>
      {%- endfor %}
      {%- endif %}

    </tbody>
  </table>

  <table class="sum-tbl-outer">
    <tr>
      <td class="sum-left" style="width:58%">
        {%- if d.is_flexo %}
        <div>Sticker Size (L * W) : {{ (f.get('product_length_mm',0)|int) }}*{{ (f.get('product_width_mm',0)|int) }}</div>
        <div>Ups : {{ s.get('ups',0)|int }}</div>
        <div>Colors : {{ d.doc.no_of_colors or 0 }}</div>
        <div>Stickers per Reel : {{ s.get('stickers_per_reel',0)|int }}</div>
        <div>Gold Color: {{ 'YES' if d.has_gold else 'NO' }}, Silver Color : {{ 'YES' if d.has_silver else 'NO' }}</div>
        <div>Material Width : {{ f.get('reel_width_mm',0)|int }}</div>
        {%- else %}
        {%- if d.doc.carton_size %}<div>Ctn Size : {{ d.doc.carton_size }}</div>{%- endif %}
        {%- if d.full_sheet_l %}<div>F.Sheet Size : {{ d.full_sheet_l|int }} x {{ d.full_sheet_w|int }} INCH</div>{%- endif %}
        {%- if d.cut_sheet_l %}<div>C.Sheet Size : {{ d.cut_sheet_l|int }} x {{ d.cut_sheet_w|int }} INCH</div>{%- endif %}
        <div>Cut Sheet Ups : {{ s.get('cut_sheet_ups',0)|int }}</div>
        <div>Full Sheet Ups : {{ (f.get('no_of_ups') or d.doc.no_of_ups or 0)|int }}</div>
        <div>Cuts : {{ d.doc.no_of_cuts or 0 }}</div>
        <div>Colors : {{ d.doc.no_of_colors or 0 }}</div>
        {%- endif %}
      </td>
      <td style="width:42%">
        <table class="sum-right-tbl">
          <tr><td>Order Quantity</td>     <td>{{ d.item_qty|int }}</td></tr>
          <tr><td>Net Cost</td>           <td>{{ fmt(d.net_cost) }}</td></tr>
          {%- if d.extra_prod_amt %}
          <tr><td>Extra Production Cost ({{ '{:g}'.format(d.extra_prod_pct) }}% of Production)</td><td>{{ fmt(d.extra_prod_amt) }}</td></tr>
          {%- endif %}
          <tr><td>Total Value</td>        <td>{{ fmt(d.grand_total) }}</td></tr>
          <tr><td>Unit Cost</td>          <td>{{ fmt(d.unit_cost) }}</td></tr>
          <tr><td>SSCL 2.5 %</td>         <td>{{ fmt(d.sscl_per_unit) }}</td></tr>
          <tr><td>Profit Margin</td>      <td>{{ d.profit_margin|int }} %</td></tr>
          {%- if d.is_flexo %}
          <tr><td>Selling Price</td>      <td>{{ fmt(d.sell_total) }}</td></tr>
          {%- endif %}
          <tr><td>Quoted Price</td>       <td>{{ fmt(d.sell_unit) }}</td></tr>
          <tr><td>VAT 18%</td>            <td>{{ fmt(d.vat_per_unit) }}</td></tr>
          <tr class="sep"><td>Final Value</td><td>{{ fmt(d.final_value) }}</td></tr>
          <tr><td>Material Contribution</td><td>{{ fmt(d.mat_contrib) }}</td></tr>
        </table>
      </td>
    </tr>
  </table>

  <div class="lbl">Remarks :</div>
  <div style="margin-left:12px; margin-bottom:12px; font-size:11.5px; white-space:pre-line;">{{ f.get('remarks','') }}</div>

  <div class="lbl">Materials :</div>
  <table class="mat-tbl">
    <thead>
      <tr>
        <th style="width:38%">Material</th>
        <th>Type</th><th>Quantity</th><th>Tolerance</th><th>Reissue</th><th>Unit</th>
      </tr>
    </thead>
    <tbody>
      <tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td></tr>
    </tbody>
  </table>

</div>
